def get_shape_signature(grid, from_r, from_c):
    """Get set of relative coordinates for a connected component starting at (from_r, from_c)"""
    visited = set()
    queue = deque([(from_r, from_c)])
    signature = set()

    while queue:
        rr, cc = queue.popleft()
        if (rr, cc) in visited:
            continue
        visited.add((rr, cc))
        signature.add((rr, cc))

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = rr + dr, cc + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == grid[rr][cc] and (nr, nc) not in visited:
                queue.append((nr, nc))

    return signature

def find_colors_with_shape(grid, shape):
    """Find all colors that have this exact shape (normalized) multiple times in grid"""
    color_shapes = {}

    for color in [x for x in range(10) if x not in [0, 3]]:
        seen_norm = set()
        count = 0

        for start_r in range(len(grid)):
            for start_c in range(len(grid[0])):
                if grid[start_r][start_c] == color:
                    shape_sig = get_shape_signature(grid, start_r, start_c)
                    if len(shape_sig) == len(shape):
